// Horizon, Demo: one continuous descent from orbit to a heartbeat. Eleven stops, each an idea, each in full 3-D.
// Two worlds: the valley (real elevation around Timure, 1 unit = 100 m) and an invented collapsed building (1 unit = 1 m).
// The fall through haze hides the change from one to the other. Nothing allocates in the frame loop.
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
