  for (let i = 0; i < p.count; i++) { q.fromBufferAttribute(p, i); const key = q.x.toFixed(3) + q.y.toFixed(3) + q.z.toFixed(3); if (!cache.has(key)) { const s = q.clone(); for (const [n, d] of cuts) { const e = s.dot(n) - d; if (e > 0) s.addScaledVector(n, -e); } s.x += 0.035 * R.n(); s.y += 0.025 * R.n(); s.z += 0.035 * R.n(); cache.set(key, s); } const s = cache.get(key); p.setXYZ(i, s.x, s.y, s.z); }
